import { DEVELOPER } from "./actionTypes";

export const initialState={
developers:[],
user:   {},
arr: []
}

function reducer(state=initialState, action) {
    switch (action.type) {
      case USER:
        return ({...state,  arr: [...state.arr, 4]})
      default:
        return state;
    }
  }

  export default reducer
